     */
    func applyMetadata(result: MetadataResult) throws  -> UInt64

    /**
     * Apply one bounded platform metadata window and return the new generation.
     */
    func applyMetadataBatch(results: [MetadataResult]) throws  -> UInt64

    /**
     * Whole-document choices for one ordered M3U conflict.
     */
    func conflictChoiceRows(groupId: String) throws  -> [TextRow]

    /**
     * Every unresolved music conflict, including manual-only audio/PLS.
     */
    func conflictRows() throws  -> [ConflictRow]

    /**
     * Create an empty canonical `.m3u`; returns its opaque id.
     */
    func createPlaylist(command: CreatePlaylistCommand) throws  -> String

    /**
     * Delete one confirmation-gated playlist.
     */
    func deletePlaylist(command: DeletePlaylistCommand) throws

    /**
     * Empty-folder, no-match, or content.
     */
    func libraryContentState() throws  -> LibraryContentState

    /**
     * Current view generation.
     */
    func libraryGeneration() throws  -> UInt64

    /**
     * Cached / current rows the host can paint without a metadata pass.
     */
    func libraryPaintRows() throws  -> [LibraryPaintRow]

    /**
     * Cheap whole-screen structure as section `text-row`s.
     */
    func librarySectionRows() throws  -> [TextRow]

    /**
     * Display-ready media items for one visible window.
     */
    func libraryTrackRows(sectionId: String, offset: UInt64, limit: UInt64, generation: UInt64) throws  -> [MediaItem]

    /**
     * One minimal media playback source.
     */
    func mediaSource(trackId: String) throws  -> MediaSource

    /**
     * Windowed host work for metadata extraction.
     */
    func metadataRequests(offset: UInt64, limit: UInt64) throws  -> [MetadataRequest]

    /**
     * Move one entry; returns the replacement content token.
     */
    func movePlaylistEntry(command: MovePlaylistEntryCommand) throws  -> String

    /**
     * Tracks still waiting on host metadata after a warm reload.
     */
    func pendingMetadataCount() throws  -> UInt64

    /**
     * Display-ready detail actions and enablement.
     */
    func playlistActionRows(playlistId: String) throws  -> [ActionRow]

    /**
     * Current token for typed playlist edits.
     */
    func playlistContentToken(playlistId: String) throws  -> String

    /**
     * Resolved playlist entries as minimal AVFoundation/gstreamer sources.
     */
    func playlistEntryMediaSources(playlistId: String) throws  -> [PlaylistEntryMediaSource]

    /**
     * Ordered playlist entry rows, including missing/unsupported values.
     */
    func playlistEntryRows(playlistId: String) throws  -> [TextRow]

    /**
     * Display-ready playlist list.
     */
    func playlistRows() throws  -> [TextRow]

    /**
     * Re-walk the selected folder, preserving metadata for unchanged ids.
     */
    func reload() throws

    /**
     * Remove selected entries; returns the replacement content token.
     */
    func removePlaylistEntries(command: RemovePlaylistEntriesCommand) throws  -> String

    /**
     * Explicitly apply one R8-R11 conflict decision.
     */
    func resolveConflict(command: ResolveConflictCommand) throws

    /**
     * Persist the disposable snapshot after a walk and host metadata.
     */
    func saveLibraryCache(cachePath: String) throws

    /**
     * Non-fatal scan issues as status rows.
     */
    func scanIssueRows() throws  -> [StatusRow]

    /**
     * Global search across tracks, albums, artists, and playlists.
     */
    func searchHits(query: String) throws  -> [SearchHit]

    /**
     * Apply search/sort intent and return the new generation.
     */
    func setLibraryView(command: SetLibraryViewCommand) throws  -> UInt64

    /**
     * Core-formatted facts for the Settings Info section.
     */
    func settingsInfoRows() throws  -> [TextRow]

}
