/**
 * Typed, display-ready failures (ADR 0003 R8).
 */
public
enum MusicError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    /**
     * Local file operation failed.
     */
    case Io(
        /**
         * Display-ready message.
         */message: String,
        /**
         * Retry or choose another folder.
         */userActionable: Bool
    )
    /**
     * Playlist bytes cannot be interpreted safely.
     */
    case InvalidPlaylist(
        /**
         * Display-ready message.
         */message: String,
        /**
         * The file can be repaired externally.
         */userActionable: Bool
    )
    /**
     * Opaque id no longer resolves.
     */
    case NotFound(
        /**
         * Display-ready message.
         */message: String,
        /**
         * Reloading can recover.
         */userActionable: Bool
    )
    /**
     * Typed command is invalid.
     */
    case InvalidCommand(
        /**
         * Display-ready message.
         */message: String,
        /**
         * Submitted values can be changed.
         */userActionable: Bool
    )
    /**
     * Playlist changed externally.
     */
    case StalePlaylist(
        /**
         * Display-ready message.
         */message: String,
        /**
         * Reopen and retry.
         */userActionable: Bool
    )
    /**
     * Visible window generation is stale.
     */
    case StaleGeneration(
        /**
         * Display-ready message.
         */message: String,
        /**
         * Re-read section structure and retry.
         */userActionable: Bool
    )
    /**
     * Conflict needs a source choice.
     */
    case NeedsChoice(
        /**
         * Display-ready message.
         */message: String,
        /**
         * Choosing a source recovers.
         */userActionable: Bool
    )
    /**
     * Audio/PLS conflict is outside this command surface.
     */
    case UnsupportedConflict(
        /**
         * Display-ready message.
         */message: String,
        /**
         * User can resolve the files externally.
         */userActionable: Bool
    )






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

#if compiler(>=6)
extension MusicError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMusicError: FfiConverterRustBuffer {
    typealias SwiftType = MusicError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MusicError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .Io(
            message: try FfiConverterString.read(from: &buf),
            userActionable: try FfiConverterBool.read(from: &buf)
            )
        case 2: return .InvalidPlaylist(
            message: try FfiConverterString.read(from: &buf),
            userActionable: try FfiConverterBool.read(from: &buf)
            )
        case 3: return .NotFound(
            message: try FfiConverterString.read(from: &buf),
            userActionable: try FfiConverterBool.read(from: &buf)
            )
        case 4: return .InvalidCommand(
            message: try FfiConverterString.read(from: &buf),
            userActionable: try FfiConverterBool.read(from: &buf)
            )
        case 5: return .StalePlaylist(
            message: try FfiConverterString.read(from: &buf),
            userActionable: try FfiConverterBool.read(from: &buf)
            )
        case 6: return .StaleGeneration(
            message: try FfiConverterString.read(from: &buf),
            userActionable: try FfiConverterBool.read(from: &buf)
            )
        case 7: return .NeedsChoice(
            message: try FfiConverterString.read(from: &buf),
            userActionable: try FfiConverterBool.read(from: &buf)
            )
        case 8: return .UnsupportedConflict(
            message: try FfiConverterString.read(from: &buf),
            userActionable: try FfiConverterBool.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MusicError, into buf: inout [UInt8]) {
        switch value {





        case let .Io(message,userActionable):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(userActionable, into: &buf)


        case let .InvalidPlaylist(message,userActionable):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(userActionable, into: &buf)


        case let .NotFound(message,userActionable):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(userActionable, into: &buf)


        case let .InvalidCommand(message,userActionable):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(userActionable, into: &buf)


        case let .StalePlaylist(message,userActionable):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(userActionable, into: &buf)


        case let .StaleGeneration(message,userActionable):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(userActionable, into: &buf)


        case let .NeedsChoice(message,userActionable):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(userActionable, into: &buf)


        case let .UnsupportedConflict(message,userActionable):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(userActionable, into: &buf)

        }
    }
}


